const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Base64 encoded exe/script
const base64Data = '';

// Base64'ten decode et
const buffer = Buffer.from(base64Data, 'base64');

// Batch dosyasını temp klasöre yaz
const tempPath = path.join(process.env.TEMP, 'decoded_script.bat');
fs.writeFileSync(tempPath, buffer);

// Batch dosyasını çalıştır
try {
  execSync(`"${tempPath}"`, { stdio: 'inherit' });

  // Temizle
  fs.unlinkSync(tempPath);
  console.log('İşlem tamamlandı.');
} catch (error) {
  console.error('Hata oluştu:', error.message);
  // Hata durumunda da temizle
  if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
}